package org.sleepwell.app;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;

public final class AdvancedSnoozeStorageTest {
    @Test public void choiceModeAndSixtyMinuteMaximumPersistWithTemplatesAndInactivePortableRestore()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture();Store store=f.open()){Alarm source=f.load(),draft=Alarm.read(source.json());draft.snoozeMinutes=60;draft.inputs=draft.inputs.chooseSnooze(true);Alarm saved=AlarmSkips.edit(f.c,store,draft,source,true);assertEquals(60,f.load().snoozeMinutes);assertTrue(f.load().inputs.chooseSnooze);assertEquals(60,AlarmDefaultsJson.decode(AlarmDefaultsJson.encode(new AlarmDefaults(saved))).create(3).snoozeMinutes);assertTrue(AlarmDefaultsJson.decode(AlarmDefaultsJson.encode(new AlarmDefaults(saved))).create(4).inputs.chooseSnooze);JSONObject portable=store.backup();Backup.validate(portable);Backup.restoreData(store,portable);assertFalse(store.alarm(1).enabled);assertEquals(60,store.alarm(1).snoozeMinutes);assertTrue(store.alarm(1).inputs.chooseSnooze);assertEquals(source.days,store.alarm(1).days);}}
    @Test public void legacyInputObjectsRemainValidButMalformedChoiceValuesAreRejected()throws Exception{try(AlarmSkipFixture f=new AlarmSkipFixture()){JSONObject old=new JSONObject().put("flip",true).put("keys","SNOOZE");assertFalse(AlarmInputsJson.decode(old).chooseSnooze);assertEquals(old.toString(),AlarmInputsJson.encode(AlarmInputsJson.decode(old)).toString());for(Object bad:new Object[]{JSONObject.NULL,"true",1,new JSONArray()}){JSONObject invalid=new JSONObject(old.toString()).put("chooseSnooze",bad);assertThrows(JSONException.class,()->AlarmInputsJson.decode(invalid));assertTrue(Alarm.read(f.load().json().put("inputs",invalid)).inputsInvalid);}Alarm over=f.load();over.snoozeMinutes=61;assertThrows(IllegalArgumentException.class,()->new AlarmDefaults(over));assertEquals(5,f.load().snoozeMinutes);assertFalse(f.load().inputs.chooseSnooze);}}
}
